package com.mindbridge.safety.review;  import static org.assertj.core.api.Assertions.assertThat; import static org.assertj.core.api.Assertions.assertThatThrownBy; import static org.mockito.ArgumentMatchers.any; import static org.mockito.ArgumentMatchers.anyList; import static org.mockito.ArgumentMatchers.anyLong; import static org.mockito.ArgumentMatchers.anyString; import static org.mockito.ArgumentMatchers.eq; import static org.mockito.Mockito.never; import static org.mockito.Mockito.times; import static org.mockito.Mockito.verify; import static org.mockito.Mockito.when;  import com.mindbridge.common.audit.AuditActorType; import com.mindbridge.common.audit.AuditActions; import com.mindbridge.common.audit.AuditCategory; import com.mindbridge.common.audit.AuditService; import com.mindbridge.safety.event.SafetyEventStatus; import com.mindbridge.safety.event.domain.SafetyEvent; import com.mindbridge.safety.event.exception.SafetyEventInputException; import com.mindbridge.safety.event.repository.SafetyActionRepository; import com.mindbridge.safety.event.repository.SafetyEventRepository; import com.mindbridge.safety.event.repository.SafetyEventSourceRepository; import com.mindbridge.safety.review.dto.SafetyEventSummaryResponse; import com.mindbridge.safety.review.dto.SubmitReviewRequest; import java.util.List; import java.util.Optional; import java.util.UUID; import org.junit.jupiter.api.BeforeEach; import org.junit.jupiter.api.DisplayName; import org.junit.jupiter.api.Nested; import org.junit.jupiter.api.Test; import org.mockito.ArgumentCaptor; import org.mockito.InjectMocks; import org.mockito.Mock; import org.mockito.MockitoAnnotations; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.data.domain.Page; import org.springframework.data.domain.PageImpl; import org.springframework.data.domain.PageRequest; import org.springframework.data.domain.Pageable;  /**  * Unit test for {@link ExpertReviewService}. Uses mocks for all  * dependencies so the test exercises the service's logic without  * needing a Spring context (and therefore without needing JPA entity  * scanning — which is broken in the current untracked G2 baseline  * because SafetyEventSource is a POJO rather than an @Entity).  *  * <p>Coverage mirrors the integration test in intent:  * <ul>  *   <li>listEvents: filter push-down semantics (covered via the  *       repository methods it invokes)</li>  *   <li>getEventDetailAndRecordOpened: emits audit row, throws on  *       missing event</li>  *   <li>submitReview: happy path + transition rules + duplicate  *       rejection + closed-event rejection + null reviewer + DISMISS  *       note rule</li>  * </ul>  */ @DisplayName("ExpertReviewService unit") class ExpertReviewServiceTest {      @Mock private SafetyEventRepository eventRepository;     @Mock private SafetyEventSourceRepository sourceRepository;     @Mock private SafetyActionRepository actionRepository;     @Mock private ExpertReviewRepository reviewRepository;     @Mock private AuditService auditService;      @InjectMocks private ExpertReviewService service;      @BeforeEach     void setUp() {         MockitoAnnotations.openMocks(this);     }      private SafetyEvent eventWith(SafetyEventStatus status, short level) {         SafetyEvent e = mockSafetyEvent(UUID.randomUUID(), status, level);         return e;     }      private static SafetyEvent mockSafetyEvent(UUID id, SafetyEventStatus status, short level) {         SafetyEvent e = org.mockito.Mockito.mock(SafetyEvent.class);         when(e.getId()).thenReturn(id);         when(e.getStatus()).thenReturn(status);         when(e.getRiskLevel()).thenReturn(level);         when(e.getUserId()).thenReturn(UUID.randomUUID());         return e;     }      @Nested     @DisplayName("listEvents filter push-down")     class ListEvents {          @Test         @DisplayName("no filter uses findAll(pageable)")         void noFilter() {             SafetyEvent e1 = eventWith(SafetyEventStatus.OPEN, (short) 3);             Page<SafetyEvent> page = new PageImpl<>(List.of(e1));             when(eventRepository.findAll(any(Pageable.class))).thenReturn(page);             when(reviewRepository.countBySafetyEventId(any(UUID.class))).thenReturn(0L);              Page<SafetyEventSummaryResponse> result =                     service.listEvents(null, null, PageRequest.of(0, 20));              assertThat(result.getContent()).hasSize(1);             verify(eventRepository).findAll(any(Pageable.class));             verify(eventRepository, never()).findByStatus(any(), any());             verify(eventRepository, never()).findByRiskLevel(any(), any());         }          @Test         @DisplayName("status filter uses findByStatus")         void statusFilter() {             SafetyEvent e1 = eventWith(SafetyEventStatus.OPEN, (short) 3);             Page<SafetyEvent> page = new PageImpl<>(List.of(e1));             when(eventRepository.findByStatus(eq(SafetyEventStatus.OPEN), any(Pageable.class)))                     .thenReturn(page);             when(reviewRepository.countBySafetyEventId(any(UUID.class))).thenReturn(0L);              service.listEvents(SafetyEventStatus.OPEN, null, PageRequest.of(0, 20));              verify(eventRepository).findByStatus(eq(SafetyEventStatus.OPEN), any(Pageable.class));         }          @Test         @DisplayName("riskLevel filter uses findByRiskLevel")         void riskLevelFilter() {             SafetyEvent e1 = eventWith(SafetyEventStatus.OPEN, (short) 3);             Page<SafetyEvent> page = new PageImpl<>(List.of(e1));             when(eventRepository.findByRiskLevel(eq((short) 3), any(Pageable.class)))                     .thenReturn(page);             when(reviewRepository.countBySafetyEventId(any(UUID.class))).thenReturn(0L);              service.listEvents(null, Short.valueOf((short) 3), PageRequest.of(0, 20));              verify(eventRepository).findByRiskLevel(eq((short) 3), any(Pageable.class));         }          @Test         @DisplayName("combined filter uses findByStatusAndRiskLevel")         void combinedFilter() {             SafetyEvent e1 = eventWith(SafetyEventStatus.OPEN, (short) 4);             Page<SafetyEvent> page = new PageImpl<>(List.of(e1));             when(eventRepository.findByStatusAndRiskLevel(                     eq(SafetyEventStatus.OPEN), eq((short) 4), any(Pageable.class)))                     .thenReturn(page);             when(reviewRepository.countBySafetyEventId(any(UUID.class))).thenReturn(0L);              service.listEvents(SafetyEventStatus.OPEN, Short.valueOf((short) 4),                     PageRequest.of(0, 20));              verify(eventRepository).findByStatusAndRiskLevel(                     eq(SafetyEventStatus.OPEN), eq((short) 4), any(Pageable.class));         }          @Test         @DisplayName("reviewCount comes from countBySafetyEventId")         void reviewCount() {             SafetyEvent e1 = eventWith(SafetyEventStatus.OPEN, (short) 3);             Page<SafetyEvent> page = new PageImpl<>(List.of(e1));             when(eventRepository.findAll(any(Pageable.class))).thenReturn(page);             when(reviewRepository.countBySafetyEventId(e1.getId())).thenReturn(5L);              Page<SafetyEventSummaryResponse> result =                     service.listEvents(null, null, PageRequest.of(0, 20));              assertThat(result.getContent().get(0).reviewCount()).isEqualTo(5);         }     }      @Nested     @DisplayName("getEventDetailAndRecordOpened")     class Detail {          @Test         @DisplayName("emits EXPERT_REVIEW_OPENED audit row")         void emitsAudit() {             UUID id = UUID.randomUUID();             SafetyEvent e = eventWith(SafetyEventStatus.OPEN, (short) 3);             when(eventRepository.findById(id)).thenReturn(Optional.of(e));             when(sourceRepository.findBySafetyEventId(id)).thenReturn(List.of());             when(actionRepository.findBySafetyEventId(id)).thenReturn(List.of());             when(reviewRepository.findBySafetyEventId(eq(id), any(Pageable.class)))                     .thenReturn(new PageImpl<>(List.of()));              service.getEventDetailAndRecordOpened(id);              verify(auditService).record(                     eq(AuditCategory.SAFETY),                     eq(AuditActions.EXPERT_REVIEW_OPENED),                     eq(AuditActorType.USER),                     eq(null),                     eq("SafetyEvent"),                     eq(id),                     anyString());         }          @Test         @DisplayName("missing event throws SafetyEventInputException")         void missing() {             UUID id = UUID.randomUUID();             when(eventRepository.findById(id)).thenReturn(Optional.empty());             assertThatThrownBy(() -> service.getEventDetailAndRecordOpened(id))                     .isInstanceOf(SafetyEventInputException.class)                     .hasMessageContaining("not found");             verify(auditService, never()).record(any(), any(), any(), any(), any(), any(), any());         }     }      @Nested     @DisplayName("submitReview")     class Submit {          @Test         @DisplayName("happy path: creates row, transitions OPEN, audits")         void happy() {             UUID eventId = UUID.randomUUID();             UUID reviewerId = UUID.randomUUID();             SafetyEvent e = eventWith(SafetyEventStatus.OPEN, (short) 3);             when(eventRepository.findById(eventId)).thenReturn(Optional.of(e));             when(reviewRepository.existsBySafetyEventIdAndReviewerId(eventId, reviewerId))                     .thenReturn(false);             ExpertReview saved = ExpertReview.create(                     UUID.randomUUID(), eventId, reviewerId,                     ExpertReviewDecision.ESCALATE, "followup");             when(reviewRepository.save(any(ExpertReview.class))).thenReturn(saved);              var response = service.submitReview(                     eventId, reviewerId,                     new SubmitReviewRequest(ExpertReviewDecision.ESCALATE, "followup"));              assertThat(response.decision()).isEqualTo(ExpertReviewDecision.ESCALATE);             verify(e).markUnderReview();             verify(eventRepository).save(e);             ArgumentCaptor<String> actionCap = ArgumentCaptor.forClass(String.class);             verify(auditService).record(                     eq(AuditCategory.SAFETY),                     actionCap.capture(),                     eq(AuditActorType.USER),                     eq(reviewerId),                     eq("SafetyEvent"),                     eq(eventId),                     anyString());             assertThat(actionCap.getValue()).isEqualTo(AuditActions.EXPERT_REVIEW_DECIDED);         }          @Test         @DisplayName("does NOT re-transition UNDER_REVIEW")         void noDoubleTransition() {             UUID eventId = UUID.randomUUID();             UUID reviewerId = UUID.randomUUID();             SafetyEvent e = eventWith(SafetyEventStatus.UNDER_REVIEW, (short) 3);             when(eventRepository.findById(eventId)).thenReturn(Optional.of(e));             when(reviewRepository.existsBySafetyEventIdAndReviewerId(eventId, reviewerId))                     .thenReturn(false);             when(reviewRepository.save(any(ExpertReview.class)))                     .thenAnswer(inv -> inv.getArgument(0));              service.submitReview(eventId, reviewerId,                     new SubmitReviewRequest(ExpertReviewDecision.NO_ACTION, null));              verify(e, never()).markUnderReview();             verify(eventRepository, never()).save(e);         }          @Test         @DisplayName("DISMISS without note rejected")         void dismissNoNote() {             UUID eventId = UUID.randomUUID();             UUID reviewerId = UUID.randomUUID();             SafetyEvent e = eventWith(SafetyEventStatus.OPEN, (short) 3);             when(eventRepository.findById(eventId)).thenReturn(Optional.of(e));              assertThatThrownBy(() -> service.submitReview(eventId, reviewerId,                     new SubmitReviewRequest(ExpertReviewDecision.DISMISS, null)))                     .isInstanceOf(SafetyEventInputException.class)                     .hasMessageContaining("Note is required");         }          @Test         @DisplayName("DISMISS with blank note rejected")         void dismissBlank() {             UUID eventId = UUID.randomUUID();             UUID reviewerId = UUID.randomUUID();             SafetyEvent e = eventWith(SafetyEventStatus.OPEN, (short) 3);             when(eventRepository.findById(eventId)).thenReturn(Optional.of(e));              assertThatThrownBy(() -> service.submitReview(eventId, reviewerId,                     new SubmitReviewRequest(ExpertReviewDecision.DISMISS, "   ")))                     .isInstanceOf(SafetyEventInputException.class);         }          @Test         @DisplayName("duplicate by same reviewer rejected")         void duplicate() {             UUID eventId = UUID.randomUUID();             UUID reviewerId = UUID.randomUUID();             SafetyEvent e = eventWith(SafetyEventStatus.OPEN, (short) 3);             when(eventRepository.findById(eventId)).thenReturn(Optional.of(e));             when(reviewRepository.existsBySafetyEventIdAndReviewerId(eventId, reviewerId))                     .thenReturn(true);              assertThatThrownBy(() -> service.submitReview(eventId, reviewerId,                     new SubmitReviewRequest(ExpertReviewDecision.NO_ACTION, null)))                     .isInstanceOf(DataIntegrityViolationException.class);         }          @Test         @DisplayName("closed event (RESOLVED) rejected")         void closed() {             UUID eventId = UUID.randomUUID();             UUID reviewerId = UUID.randomUUID();             SafetyEvent e = eventWith(SafetyEventStatus.RESOLVED, (short) 3);             when(eventRepository.findById(eventId)).thenReturn(Optional.of(e));              assertThatThrownBy(() -> service.submitReview(eventId, reviewerId,                     new SubmitReviewRequest(ExpertReviewDecision.NO_ACTION, null)))                     .isInstanceOf(SafetyEventInputException.class)                     .hasMessageContaining("closed event");         }          @Test         @DisplayName("null reviewer rejected at the boundary")         void nullReviewer() {             UUID eventId = UUID.randomUUID();             assertThatThrownBy(() -> service.submitReview(eventId, null,                     new SubmitReviewRequest(ExpertReviewDecision.NO_ACTION, null)))                     .isInstanceOf(NullPointerException.class);         }          @Test         @DisplayName("missing event rejected")         void missing() {             UUID eventId = UUID.randomUUID();             when(eventRepository.findById(eventId)).thenReturn(Optional.empty());             assertThatThrownBy(() -> service.submitReview(eventId, UUID.randomUUID(),                     new SubmitReviewRequest(ExpertReviewDecision.NO_ACTION, null)))                     .isInstanceOf(SafetyEventInputException.class);         }     } }